    body {
      margin: 0;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background: radial-gradient(circle at top left, #fef4ed 0, #f5f7fb 28%, #f5f7fb 100%);
      color: var(--text);
      line-height: 1.5;
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    img,
    svg {
      max-width: 100%;
      display: block;
    }

    button,
    input {
      font: inherit;
    }

    button {
      cursor: pointer;
    }

    :focus-visible {
      outline: 3px solid var(--accent);
      outline-offset: 3px;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--text);
      color: #fff;
      transform: translateY(-200%);
      transition: transform 0.2s ease;
      z-index: 10;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    .shell {
      width: var(--container);
      margin: 0 auto;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      padding: 0.45rem 0.85rem;
      border-radius: 999px;
      background: var(--accent-soft);
      color: var(--accent-strong);
      font-size: 0.9rem;
      font-weight: 700;
      letter-spacing: 0.01em;
    }

    .site-header {
      padding: 1rem 0 0;
    }

    .announcement {
      display: flex;
      justify-content: center;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: #fff3e6;
      color: #6e3a00;
      font-size: 0.95rem;
      font-weight: 600;
    }

    .nav {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 1rem 0 1.5rem;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 0.8rem;
      font-weight: 800;
      letter-spacing: 0.02em;
    }

    .brand-mark {
      width: 2.8rem;
      height: 2.8rem;
      border-radius: 0.95rem;
      background: linear-gradient(135deg, var(--accent) 0%, #72a5ff 100%);
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.35);
    }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 1.1rem;
      padding: 0;
      margin: 0;
      list-style: none;
      flex-wrap: wrap;
    }

    .nav-links a {
      color: var(--muted);
      font-weight: 600;
    }

    .nav-actions {
      display: flex;
      gap: 0.75rem;
      align-items: center;
      flex-wrap: wrap;
    }

    .button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 0.5rem;
      min-height: 2.9rem;
      padding: 0.8rem 1.1rem;
      border-radius: 999px;
      border: 1px solid transparent;
      font-weight: 700;
      transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
    }

    .button:hover {
      transform: translateY(-1px);
    }

    .button-primary {
      background: var(--accent);
      color: #fff;
      box-shadow: 0 10px 24px rgba(36, 87, 245, 0.25);
    }

    .button-primary:hover,
    .button-primary:focus-visible {
      background: var(--accent-strong);
    }

    .button-secondary {
      background: var(--surface);
      border-color: var(--line);
      color: var(--text);
    }

    .hero {
      display: grid;
      grid-template-columns: minmax(0, 1.05fr) minmax(280px, 0.95fr);
      gap: 1.5rem;
      align-items: stretch;
      padding-bottom: 2rem;
    }

    .hero-copy,
    .hero-showcase,
    .section-card,
    .spotlight-card,
    .newsletter {
      background: var(--surface);
      border: 1px solid rgba(213, 222, 235, 0.8);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow);
    }

    .hero-copy {
      padding: clamp(1.6rem, 4vw, 3rem);
    }

    h1,
    h2,
    h3 {
      margin: 0;
      line-height: 1.08;
    }

    h1 {
      font-size: clamp(2.6rem, 5vw, 4.8rem);
      margin-top: 1rem;
      max-width: 10ch;
      letter-spacing: -0.04em;
    }

    .hero-copy p {
      font-size: 1.08rem;
      color: var(--muted);
      max-width: 34rem;
      margin: 1rem 0 1.6rem;
    }

    .hero-actions,
    .hero-notes,
    .section-header,
    .filters,
    .newsletter-row {
      display: flex;
      gap: 0.9rem;
      flex-wrap: wrap;
      align-items: center;
    }

    .hero-notes {
      margin-top: 1.5rem;
      color: var(--muted);
      font-weight: 600;
    }

    .hero-notes span {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      padding: 0.6rem 0.8rem;
      border-radius: 999px;
      background: var(--surface-alt);
    }

    .hero-showcase {
      display: grid;
      grid-template-rows: auto auto;
      gap: 1rem;
      padding: 1.2rem;
      overflow: hidden;
      position: relative;
      background:
        radial-gradient(circle at top right, #cddcff 0, #ffffff 36%, #ffffff 100%);
    }

    .showcase-panel {
      display: grid;
      grid-template-columns: 1.1fr 0.9fr;
      gap: 1rem;
      align-items: end;
      min-height: 21rem;
      padding: 1.2rem;
      border-radius: 1.4rem;
      background: linear-gradient(145deg, #1d2540 0%, #2d427c 100%);
      color: #fff;
      position: relative;
      overflow: hidden;
    }

    .showcase-panel::after {
      content: "";
      position: absolute;
      inset: auto -10% -20% auto;
      width: 12rem;
      height: 12rem;
      border-radius: 50%;
      background: radial-gradient(circle, rgba(255, 255, 255, 0.35) 0%, rgba(255, 255, 255, 0) 72%);
    }

    .showcase-copy p,
    .meta-text,
    .card-copy p,
    .article-copy p,
    .newsletter p,
    .countdown-note {
      color: inherit;
      margin: 0.65rem 0 0;
    }

    .showcase-copy p,
    .meta-text,
    .card-copy p,
    .article-copy p,
    .newsletter p {
      opacity: 0.9;
    }

    .visual-stack {
      position: relative;
      min-height: 14rem;
    }

    .visual-stack::before,
    .visual-stack::after,
    .visual-core {
      content: "";
      position: absolute;
      border-radius: 2rem;
      background: linear-gradient(160deg, #ffffff 0%, #d7e2ff 100%);
      box-shadow: 0 20px 30px rgba(13, 21, 44, 0.25);
    }

    .visual-core {
      width: 9rem;
      height: 11rem;
      right: 0.6rem;
      bottom: 0.6rem;
      transform: rotate(10deg);
    }

    .visual-stack::before {
      width: 6.5rem;
      height: 8.5rem;
      right: 8rem;
      bottom: 0.2rem;
      transform: rotate(-14deg);
    }

    .visual-stack::after {
      width: 5rem;
      height: 6rem;
      right: 2rem;
      bottom: 8rem;
      transform: rotate(-10deg);
      background: linear-gradient(160deg, #ffecd5 0%, #ffd08d 100%);
    }

    .showcase-meta {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 0.8rem;
    }

    .meta-card {
      padding: 1rem;
      border-radius: 1.1rem;
      background: var(--surface-alt);
    }

    .meta-label {
      font-size: 0.85rem;
      font-weight: 700;
      color: var(--muted);
      text-transform: uppercase;
      letter-spacing: 0.06em;
    }

    .meta-value {
      margin-top: 0.35rem;
      font-size: 1.25rem;
      font-weight: 800;
    }

    main {
      padding-bottom: 3rem;
    }

    section {
      margin-top: 1.5rem;
    }

    .section-card {
      padding: clamp(1.2rem, 3vw, 2rem);
    }

    .section-header {
      justify-content: space-between;
      margin-bottom: 1.2rem;
    }

    .section-header p,
    .section-kicker {
      margin: 0;
      color: var(--muted);
    }

    .filters {
      margin-bottom: 1.25rem;
    }

    .chip {
      border: 1px solid var(--line);
      background: var(--surface);
      color: var(--text);
      padding: 0.7rem 1rem;
      border-radius: 999px;
      font-weight: 700;
    }

    .chip[aria-pressed="true"] {
      background: var(--accent);
      border-color: var(--accent);
      color: #fff;
    }

    .product-grid,
    .article-grid,
    .offer-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
    }

    .product-card,
    .article-card,
    .offer-card {
      min-width: 0;
      border: 1px solid var(--line);
      border-radius: 1.4rem;
      background: var(--surface);
      overflow: hidden;
    }

    .product-card {
      display: flex;
      flex-direction: column;
    }

    .card-visual {
      min-height: 15rem;
      padding: 1rem;
      background: linear-gradient(180deg, #eef3fb 0%, #dfe7f4 100%);
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      gap: 1rem;
    }

    .visual-tile {
      flex: 1;
      min-height: 11rem;
      border-radius: 1.2rem;
      background: var(--gradient, linear-gradient(145deg, #2d427c 0%, #72a5ff 100%));
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.35);
    }

    .card-badge {
      align-self: flex-start;
      padding: 0.45rem 0.7rem;
      border-radius: 999px;
      background: #fff;
      color: var(--text);
      font-size: 0.82rem;
      font-weight: 700;
    }

    .card-copy {
      padding: 1.1rem;
    }

    .card-topline,
    .article-meta,
    .offer-meta {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 0.75rem;
      margin-bottom: 0.5rem;
      color: var(--muted);
      font-size: 0.95rem;
      font-weight: 700;
    }

    .price-row {
      display: flex;
      align-items: baseline;
      gap: 0.6rem;
      margin-top: 1rem;
      flex-wrap: wrap;
    }

    .price {
      font-size: 1.35rem;
      font-weight: 800;
    }

    .compare-price {
      color: var(--muted);
      text-decoration: line-through;
      font-weight: 600;
    }

    .card-actions {
      margin-top: 1rem;
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 0.75rem;
    }

    .mini-link {
      color: var(--accent-strong);
      font-weight: 800;
    }

    .deal-layout {
      display: grid;
      grid-template-columns: minmax(0, 1.1fr) minmax(0, 0.9fr);
      gap: 1rem;
      align-items: stretch;
    }

    .spotlight-card {
      padding: clamp(1.2rem, 3vw, 2rem);
      background: linear-gradient(145deg, #10223e 0%, #1e4c99 100%);
      color: #fff;
    }

    .countdown {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 0.75rem;
      margin-top: 1.5rem;
    }

    .countdown-unit {
      padding: 1rem 0.75rem;
      border-radius: 1rem;
      background: rgba(255, 255, 255, 0.12);
      text-align: center;
    }

    .countdown-value {
      display: block;
      font-size: 1.7rem;
      font-weight: 800;
      line-height: 1;
    }

    .countdown-label {
      margin-top: 0.4rem;
      display: block;
      font-size: 0.85rem;
      letter-spacing: 0.06em;
      text-transform: uppercase;
    }

    .countdown-note {
      margin-top: 1rem;
      font-weight: 600;
    }

    .offer-grid {
      grid-template-columns: 1fr;
    }

    .offer-card {
      padding: 1.1rem;
      background: #fff;
    }

    .offer-copy h3,
    .article-copy h3 {
      font-size: 1.2rem;
      margin-bottom: 0.4rem;
    }

    .article-card {
      display: flex;
      flex-direction: column;
    }

    .article-image {
      min-height: 12rem;
      background:
        linear-gradient(130deg, rgba(36, 87, 245, 0.12), rgba(36, 87, 245, 0.02)),
        radial-gradient(circle at top left, #ffffff 0, #e5ecfb 80%);
      position: relative;
      overflow: hidden;
    }

    .article-image::before,
    .article-image::after {
      content: "";
      position: absolute;
      border-radius: 1.5rem;
      background: linear-gradient(145deg, #72a5ff 0%, #2457f5 100%);
    }

    .article-image::before {
      width: 8rem;
      height: 8rem;
      right: 1.2rem;
      top: 1.2rem;
    }

    .article-image::after {
      width: 10rem;
      height: 5rem;
      left: 1.2rem;
      bottom: 1.2rem;
      background: linear-gradient(145deg, #ffdbb2 0%, #ffb669 100%);
    }

    .article-copy {
      padding: 1.1rem;
      display: flex;
      flex-direction: column;
      gap: 0.75rem;
      height: 100%;
    }

    .newsletter {
      margin-top: 1.5rem;
      padding: clamp(1.2rem, 3vw, 2rem);
    }

    .newsletter form {
      margin-top: 1rem;
    }

    .newsletter label {
      font-weight: 700;
      display: block;
      margin-bottom: 0.55rem;
    }

    .newsletter-row input {
      flex: 1 1 18rem;
      min-height: 3rem;
      padding: 0.8rem 1rem;
      border-radius: 999px;
      border: 1px solid var(--line);
      background: #fff;
      min-width: 0;
    }

    .helper-text,
    .form-status {
      margin-top: 0.75rem;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .form-status {
      font-weight: 700;
      min-height: 1.5rem;
    }

    .form-status[data-state="success"] {
      color: var(--success);
    }

    .form-status[data-state="error"] {
      color: #b42318;
    }

    .site-footer {
      padding: 0 0 2.5rem;
    }

    .footer-card {
      width: var(--container);
      margin: 0 auto;
      padding: 1.25rem 1.5rem;
      border-radius: 1.5rem;
      background: #13213b;
      color: #e7eefb;
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      flex-wrap: wrap;
    }

    .footer-links {
      display: flex;
      flex-wrap: wrap;
      gap: 1rem;
      padding: 0;
      margin: 0;
      list-style: none;
    }

    @media (max-width: 960px) {
      .hero,
      .deal-layout {
        grid-template-columns: 1fr;
      }

      .product-grid,
      .article-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }
    }

    @media (max-width: 700px) {
      .nav {
        flex-direction: column;
        align-items: stretch;
      }

      .nav-links,
      .nav-actions {
        justify-content: center;
      }

      .showcase-panel,
      .showcase-meta,
      .product-grid,
      .article-grid,
      .countdown {
        grid-template-columns: 1fr;
      }

      .card-visual {
        min-height: 12rem;
      }
    }

    @media (max-width: 480px) {
      h1 {
        font-size: 2.4rem;
      }

      .announcement,
      .hero-copy,
      .hero-showcase,
      .section-card,
      .spotlight-card,
      .newsletter,
      .footer-card {
        border-radius: 1.25rem;
      }
    }

    @media (forced-colors: active) {
      body {
        background: Canvas;
        color: CanvasText;
      }

      .hero-copy,
      .hero-showcase,
      .section-card,
      .spotlight-card,
      .newsletter,
      .footer-card,
      .product-card,
      .article-card,
      .offer-card,
      .announcement,
      .meta-card,
      .countdown-unit {
        background: Canvas;
        color: CanvasText;
        border: 1px solid ButtonBorder;
        box-shadow: none;
      }

      .button,
      .chip,
      .newsletter-row input {
        background: ButtonFace;
        color: ButtonText;
        border: 1px solid ButtonBorder;
      }

      .button-primary,
      .chip[aria-pressed="true"] {
        background: Highlight;
        color: HighlightText;
      }

      .brand-mark,
      .visual-tile,
      .article-image::before,
      .article-image::after,
      .visual-core,
      .visual-stack::before,
      .visual-stack::after {
        background: CanvasText;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <header class="site-header">
    <div class="shell">
      <div class="announcement">Spring preview: members get free express shipping on orders over $75.</div>
      <div class="nav">
        <a class="brand" href="#" aria-label="Northstar Supply home">
          <span class="brand-mark" aria-hidden="true"></span>
          <span>Northstar Supply</span>
        </a>

        <nav aria-label="Primary">
          <ul class="nav-links">
            <li><a href="#featured-products">Featured</a></li>
            <li><a href="#deals">Deals</a></li>
            <li><a href="#editorial">Editorial</a></li>
            <li><a href="#newsletter">Community</a></li>
          </ul>
        </nav>

        <div class="nav-actions">
          <a class="button button-secondary" href="#editorial">Style guide</a>
          <a class="button button-primary" href="#featured-products">Shop new arrivals</a>
        </div>
      </div>
    </div>
  </header>

  <main id="main-content" tabindex="-1">
    <div class="shell">
      <section class="hero" aria-labelledby="hero-title">
        <div class="hero-copy">
          <span class="eyebrow">New-season retail edit</span>
          <h1 id="hero-title">Elevated essentials for every everyday moment.</h1>
          <p>
            Discover a polished mix of home, wellness, and carry goods curated to make daily rituals feel lighter, smarter, and more intentional.
          </p>
          <div class="hero-actions">
            <a class="button button-primary" href="#featured-products">Explore products</a>
            <a class="button button-secondary" href="#deals">See today&apos;s deals</a>
          </div>
          <div class="hero-notes" aria-label="Key benefits">
            <span>48-hour dispatch</span>
            <span>Extended returns</span>
            <span>Curated editorial picks</span>
          </div>
        </div>

        <div class="hero-showcase" aria-label="Season highlight">
          <div class="showcase-panel">
            <div class="showcase-copy">
              <span class="eyebrow">Top-rated bundle</span>
              <h2>City commute kit</h2>
              <p>Weather-ready layers, modular storage, and desk-to-dinner accessories designed for flexible days.</p>
            </div>
            <div class="visual-stack" aria-hidden="true">
              <span class="visual-core"></span>
            </div>
          </div>

          <div class="showcase-meta" aria-label="Brand highlights">
            <div class="meta-card">
              <div class="meta-label">Fresh arrivals</div>
              <div class="meta-value">34 this week</div>
              <p class="meta-text">Small-batch releases from modern makers.</p>
            </div>
            <div class="meta-card">
              <div class="meta-label">Average rating</div>
              <div class="meta-value">4.8 / 5</div>
              <p class="meta-text">Trusted by shoppers who value smart details.</p>
            </div>
            <div class="meta-card">
              <div class="meta-label">Top category</div>
              <div class="meta-value">Everyday carry</div>
              <p class="meta-text">Compact pieces with premium materials.</p>
            </div>
          </div>
        </div>
      </section>

      <section id="featured-products" class="section-card" aria-labelledby="featured-title">
        <div class="section-header">
          <div>
            <span class="section-kicker">Featured products</span>
            <h2 id="featured-title">Designed to earn a place in your daily lineup.</h2>
          </div>
          <p>Filter the collection to browse what fits your routine.</p>
        </div>

        <div class="filters" aria-label="Product categories">
          <button class="chip" type="button" aria-pressed="true" data-filter="all">All</button>
          <button class="chip" type="button" aria-pressed="false" data-filter="carry">Carry</button>
          <button class="chip" type="button" aria-pressed="false" data-filter="home">Home</button>
          <button class="chip" type="button" aria-pressed="false" data-filter="wellness">Wellness</button>
        </div>

        <div id="product-grid" class="product-grid" aria-live="polite"></div>
      </section>

      <section id="deals" class="section-card" aria-labelledby="deals-title">
        <div class="section-header">
          <div>
            <span class="section-kicker">Deals</span>
            <h2 id="deals-title">Limited-time offers with a polished point of view.</h2>
          </div>
          <p>Fresh pricing resets daily at 6 PM.</p>
        </div>

        <div class="deal-layout">
          <article class="spotlight-card" aria-labelledby="deal-spotlight-title">
            <span class="eyebrow">Flash offer</span>
            <h3 id="deal-spotlight-title">Save 30% on the Weekend Reset set</h3>
            <p class="countdown-note">A soft-structure tote, insulated bottle, and linen organizer at the best price of the week.</p>

            <div class="countdown" aria-label="Time remaining for the flash offer">
              <div class="countdown-unit">
                <span class="countdown-value" id="days">00</span>
                <span class="countdown-label">Days</span>
              </div>
              <div class="countdown-unit">
                <span class="countdown-value" id="hours">00</span>
                <span class="countdown-label">Hours</span>
              </div>
              <div class="countdown-unit">
                <span class="countdown-value" id="minutes">00</span>
                <span class="countdown-label">Minutes</span>
              </div>
              <div class="countdown-unit">
                <span class="countdown-value" id="seconds">00</span>
                <span class="countdown-label">Seconds</span>
              </div>
            </div>

            <p id="countdown-status" class="countdown-note" aria-live="polite">Offer refreshes automatically at the next drop.</p>
          </article>

          <div class="offer-grid" id="offer-grid"></div>
        </div>
      </section>

      <section id="editorial" class="section-card" aria-labelledby="editorial-title">
        <div class="section-header">
          <div>
            <span class="section-kicker">Editorial</span>
            <h2 id="editorial-title">Stories, routines, and styling ideas from the Northstar journal.</h2>
          </div>
          <p>Content built to inspire smarter purchases and longer-lasting pieces.</p>
        </div>

        <div id="article-grid" class="article-grid"></div>
      </section>

      <section id="newsletter" class="newsletter" aria-labelledby="newsletter-title">
        <span class="section-kicker">Community drop alerts</span>
