        category: "carry",
        tag: "Limited color",
        description: "Double-wall stainless steel with a slim profile that fits every tote.",
        price: "$38",
        comparePrice: "$52",
        accent: "linear-gradient(145deg, #2f425f 0%, #90abc8 100%)"
      },
      {
        name: "Cloud Throw",
        category: "home",
        tag: "Soft launch",
        description: "Layered cotton texture designed for sofa corners and guest spaces.",
        price: "$86",
        comparePrice: "$108",
        accent: "linear-gradient(145deg, #b28b6f 0%, #e0c1a6 100%)"
      },
      {
        name: "Balance Roller",
        category: "wellness",
        tag: "Recovery favorite",
        description: "Dense yet responsive foam for cool-down rituals after long days.",
        price: "$46",
        comparePrice: "$58",
        accent: "linear-gradient(145deg, #425b52 0%, #87b3a2 100%)"
      }
    ];

    const offers = [
      {
        title: "Home refresh",
        detail: "Buy two décor accents and unlock an extra 15% off.",
        price: "Bundle from $68"
      },
      {
        title: "Carry upgrade",
        detail: "Complimentary pouch with every bag purchase this week.",
        price: "Gift value $22"
      },
      {
        title: "Wellness edit",
        detail: "Two-for-one on recovery tools selected by our journal team.",
        price: "From $46"
      }
    ];

    const articles = [
      {
        tag: "Journal",
        title: "How to build a home desk setup that still feels calm at 8 PM",
        description: "A quick guide to light, texture, and storage choices that lower visual noise.",
        link: "Read the workspace story"
      },
      {
        tag: "Style notes",
        title: "Five travel-ready essentials our retail team packs every single weekend",
        description: "Compact carry pieces that work harder without taking over your bag.",
        link: "Browse the packing edit"
      },
      {
        tag: "Care guide",
        title: "Why thoughtful materials matter when you want products that last",
        description: "See how we source durable finishes and help customers extend product life.",
        link: "Explore materials insight"
      }
    ];

    const productGrid = document.getElementById("product-grid");
    const offerGrid = document.getElementById("offer-grid");
    const articleGrid = document.getElementById("article-grid");
    const filterButtons = document.querySelectorAll(".chip");
    const newsletterForm = document.getElementById("newsletter-form");
    const emailInput = document.getElementById("email");
    const formStatus = document.getElementById("form-status");
    const countdownStatus = document.getElementById("countdown-status");

    function renderProducts(filter) {
      const visibleProducts = filter === "all"
        ? products
        : products.filter((product) => product.category === filter);

      productGrid.innerHTML = visibleProducts.map((product) => `
        <article class="product-card">
          <div class="card-visual">
            <span class="card-badge">${product.tag}</span>
            <div class="visual-tile" style="--gradient: ${product.accent};" aria-hidden="true"></div>
          </div>
          <div class="card-copy">
            <div class="card-topline">
              <span>${product.category}</span>
              <span>Free returns</span>
            </div>
            <h3>${product.name}</h3>
            <p>${product.description}</p>
            <div class="price-row">
              <span class="price">${product.price}</span>
              <span class="compare-price">${product.comparePrice}</span>
            </div>
            <div class="card-actions">
              <a class="mini-link" href="#newsletter">Get launch alerts</a>
              <a class="button button-secondary" href="#deals">View offer</a>
            </div>
          </div>
        </article>
      `).join("");
    }

    function renderOffers() {
      offerGrid.innerHTML = offers.map((offer) => `
        <article class="offer-card">
          <div class="offer-meta">
            <span>Today only</span>
            <span>${offer.price}</span>
          </div>
          <div class="offer-copy">
            <h3>${offer.title}</h3>
            <p>${offer.detail}</p>
          </div>
        </article>
      `).join("");
    }

    function renderArticles() {
      articleGrid.innerHTML = articles.map((article) => `
        <article class="article-card">
          <div class="article-image" aria-hidden="true"></div>
          <div class="article-copy">
            <div class="article-meta">
              <span>${article.tag}</span>
              <span>5 min read</span>
            </div>
            <h3>${article.title}</h3>
            <p>${article.description}</p>
            <a class="mini-link" href="#newsletter">${article.link}</a>
          </div>
        </article>
      `).join("");
    }

    filterButtons.forEach((button) => {
      button.addEventListener("click", () => {
        filterButtons.forEach((chip) => {
          chip.setAttribute("aria-pressed", String(chip === button));
        });
        renderProducts(button.dataset.filter);
      });
    });

    function getNextDropTime() {
      const now = new Date();
      const target = new Date(now);
      target.setHours(18, 0, 0, 0);

      if (now >= target) {
        target.setDate(target.getDate() + 1);
      }

      return target;
    }

    let nextDropTime = getNextDropTime();

    function updateCountdown() {
      const now = new Date();
      let diff = nextDropTime.getTime() - now.getTime();

      if (diff <= 0) {
        nextDropTime = getNextDropTime();
        diff = nextDropTime.getTime() - now.getTime();
        countdownStatus.textContent = "A new deal window just opened. Timer reset for the next daily drop.";
      }

      const totalSeconds = Math.floor(diff / 1000);
      const days = Math.floor(totalSeconds / 86400);
      const hours = Math.floor((totalSeconds % 86400) / 3600);
      const minutes = Math.floor((totalSeconds % 3600) / 60);
      const seconds = totalSeconds % 60;

      document.getElementById("days").textContent = String(days).padStart(2, "0");
      document.getElementById("hours").textContent = String(hours).padStart(2, "0");
      document.getElementById("minutes").textContent = String(minutes).padStart(2, "0");
      document.getElementById("seconds").textContent = String(seconds).padStart(2, "0");
    }

    function setFormStatus(message, state) {
      formStatus.textContent = message;
      formStatus.dataset.state = state || "";
    }

    newsletterForm.addEventListener("submit", (event) => {
      event.preventDefault();

      if (!emailInput.validity.valid) {
        emailInput.setAttribute("aria-invalid", "true");
        setFormStatus("Enter a valid email address to join the weekly dispatch.", "error");
        emailInput.focus();
        return;
      }

      emailInput.removeAttribute("aria-invalid");
      setFormStatus("Thanks for joining. Your first Northstar dispatch lands soon.", "success");
      newsletterForm.reset();
    });

    emailInput.addEventListener("input", () => {
      if (emailInput.validity.valid) {
        emailInput.removeAttribute("aria-invalid");
        if (formStatus.dataset.state === "error") {
          setFormStatus("", "");
        }
      }
    });

    renderProducts("all");
    renderOffers();
    renderArticles();
    updateCountdown();
    window.setInterval(updateCountdown, 1000);
  </script>
