      gap: 1.5rem;
      align-items: stretch;
      padding-bottom: 2rem;
    }

    .hero-copy,
    .hero-showcase,
    .section-card,
    .spotlight-card,
    .newsletter {
      background: var(--surface);
      border: 1px solid rgba(213, 222, 235, 0.8);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow);
    }

    .hero-copy {
      padding: clamp(1.6rem, 4vw, 3rem);
    }

    h1,
    h2,
    h3 {
      margin: 0;
      line-height: 1.08;
    }

    h1 {
      font-size: clamp(2.6rem, 5vw, 4.8rem);
      margin-top: 1rem;
      max-width: 10ch;
      letter-spacing: -0.04em;
    }

    .hero-copy p {
      font-size: 1.08rem;
      color: var(--muted);
      max-width: 34rem;
      margin: 1rem 0 1.6rem;
    }

    .hero-actions,
    .hero-notes,
    .section-header,
    .filters,
    .newsletter-row {
      display: flex;
      gap: 0.9rem;
      flex-wrap: wrap;
      align-items: center;
    }

    .hero-notes {
      margin-top: 1.5rem;
      color: var(--muted);
      font-weight: 600;
    }

    .hero-notes span {
